update public.content_variants set body = $json${"type":"multiple_choice","answer":"Good debt","options":["Good debt","Bad debt","Consumer debt","Bad debt"],"question":"Sari borrowed money to start an online shop. If the business earns more than the cost of borrowing, the debt includes...","difficulty":"beginner","explanation":"When a loan generates income that exceeds its costs, it supports financial growth."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Utang baik","options":["Utang baik","Utang buruk","Utang konsumtif","Utang macet"],"question":"Sari meminjam uang untuk memulai toko online. Jika usahanya menghasilkan lebih banyak dari biaya pinjaman, utangnya termasuk...","difficulty":"beginner","explanation":"Ketika pinjaman menghasilkan pendapatan yang melebihi biayanya, utang itu mendukung pertumbuhan keuangan."}$json$::jsonb where id = '1612ff31-a4d2-42e4-bda8-ab0089728e57';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Stop adding new debts and make a list of all debts","options":["Stop adding new debts and make a list of all debts","Borrow again to pay off old debts","Stop paying all installments","Buy necessities using a credit card"],"question":"The first step to paying off debt responsibly is...","difficulty":"beginner","explanation":"A debt list provides a clear picture and helps you choose a repayment strategy."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Berhenti menambah utang baru dan membuat daftar semua utang","options":["Berhenti menambah utang baru dan membuat daftar semua utang","Meminjam lagi untuk melunasi utang lama","Berhenti membayar semua cicilan","Membeli barang kebutuhan pakai kartu kredit"],"question":"Langkah pertama membayar utang dengan bertanggung jawab adalah...","difficulty":"beginner","explanation":"Daftar utang memberikan gambaran jelas dan membantumu memilih strategi pelunasan."}$json$::jsonb where id = '19b3af40-fa75-4c30-a2ff-f745c5c3626a';
update public.content_variants set body = $json${"text":"Sari wants to invest but doesn't want the hassle. He bought ETFIDX30 (XIIS) which automatically invests in 30 Indonesian blue-chip companies. Every month he auto-debits IDR 500,000. In 5 years, he had a diversified portfolio without needing to choose stocks one by one."}$json$::jsonb, body_id = $json${"text":"Sari ingin investasi tapi tidak mau ribet. Dia beli ETFIDX30 (XIIS) yang otomatis investasi di 30 perusahaan blue-chip Indonesia. Setiap bulan dia auto-debet Rp 500.000. Dalam 5 tahun, dia punya portofolio terdiversifikasi tanpa perlu pilih saham satu per satu."}$json$::jsonb where id = '19d4e535-fc47-45c7-8e66-898af92cbc59';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Money that will not be used in the next 6-12 months","options":["Daily expenses","Money that will not be used in the next 6-12 months","Business transactions","Buy food"],"question":"Deposits are suitable for...","difficulty":"beginner","explanation":"Deposits lock your money for a certain period (usually 1-12 months) with higher returns, suitable for medium-term goals such as emergency funds."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Uang yang tidak akan dipakai dalam 6-12 bulan ke depan","options":["Pengeluaran harian","Uang yang tidak akan dipakai dalam 6-12 bulan ke depan","Transaksi bisnis","Membeli makanan"],"question":"Deposito cocok untuk...","difficulty":"beginner","explanation":"Deposito mengunci uangmu untuk periode tertentu (biasanya 1-12 bulan) dengan imbal hasil lebih tinggi, cocok untuk tujuan jangka menengah seperti dana darurat."}$json$::jsonb where id = '1c296e5c-4446-4f8d-9a45-9ce03e0ac847';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Profits from crypto trading in Indonesia do not need to be reported for tax.","difficulty":"beginner","explanation":"Crypto-related profits and income can be taxed according to applicable regulations. Always keep transaction records."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Keuntungan dari trading kripto di Indonesia tidak perlu dilaporkan untuk pajak.","difficulty":"beginner","explanation":"Keuntungan dan pendapatan terkait kripto bisa dikenakan pajak sesuai aturan yang berlaku. Selalu simpan catatan transaksi."}$json$::jsonb where id = '1c5f5a60-89a2-4987-a0f7-3b588d9ef491';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Smart contracts","options":["Smart contracts","Credit card","Life insurance","Interest-free loan"],"question":"Ethereum is famous for adding features...","difficulty":"beginner","explanation":"Ethereum introduced smart contracts, which are programs that run automatically when certain conditions are met."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Smart contract","options":["Smart contract","Kartu kredit","Asuransi jiwa","Pinjaman tanpa bunga"],"question":"Ethereum terkenal karena menambahkan fitur...","difficulty":"beginner","explanation":"Ethereum memperkenalkan smart contract, yaitu program yang berjalan otomatis ketika kondisi tertentu terpenuhi."}$json$::jsonb where id = '1cc50037-e751-49a8-a74d-65e2e1396ee2';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Using an exchange licensed by CoFTRA","options":["Using an exchange licensed by CoFTRA","Transfer to the seller's personal account on Instagram","Buy from Telegram groups that offer low prices","Sending cash via online motorcycle taxi"],"question":"The safest way to buy crypto in Indonesia is...","difficulty":"beginner","explanation":"Bappebti licensed exchanges have KYC regulations and consumer protection. Transactions outside of that are high risk."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Menggunakan bursa berizin Bappebti","options":["Menggunakan bursa berizin Bappebti","Transfer ke rekening pribadi penjual di Instagram","Membeli dari grup Telegram yang menawarkan harga murah","Mengirim uang tunai melalui ojek online"],"question":"Cara paling aman membeli kripto di Indonesia adalah...","difficulty":"beginner","explanation":"Bursa berizin Bappebti memiliki aturan KYC dan perlindungan konsumen. Transaksi di luar itu berisiko tinggi."}$json$::jsonb where id = '1e7b2a61-9dca-40f6-9ed2-04101400112e';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"ETFs are traded on exchanges at real-time prices, mutual funds are purchased through investment managers at end-of-day NAV prices","options":["ETFs are more expensive than mutual funds","ETFs are traded on exchanges at real-time prices, mutual funds are purchased through investment managers at end-of-day NAV prices","Mutual funds can be traded on exchanges","No difference"],"question":"What are the main differences between ETFs and mutual funds?","difficulty":"intermediate","explanation":"ETFs are like shares that you can buy and sell at any time during stock exchange hours at changing prices. Mutual funds are bought and sold at NAV (Net Asset Value) prices which are calculated once at the end of the trading day."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"ETF diperdagangkan di bursa dengan harga real-time, reksa dana dibeli melalui manajer investasi dengan harga NAV akhir hari","options":["ETF lebih mahal dari reksa dana","ETF diperdagangkan di bursa dengan harga real-time, reksa dana dibeli melalui manajer investasi dengan harga NAV akhir hari","Reksa dana bisa diperdagangkan di bursa","Tidak ada perbedaan"],"question":"Apa perbedaan utama antara ETF dan reksa dana?","difficulty":"intermediate","explanation":"ETF seperti saham yang bisa kamu jual-beli kapan saja selama jam bursa dengan harga yang berubah-ubah. Reksa dana dibeli dan dijual dengan harga NAV (Net Asset Value) yang dihitung sekali di akhir hari perdagangan."}$json$::jsonb where id = '2829e1fb-8547-4de5-8288-0eaa14cdfc8b';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Pay the minimum on time and do not neglect obligations","options":["Pay the minimum on time and do not neglect obligations","Borrowing from many sources","Pay only the largest debts","Close all bank accounts"],"question":"What protects SLIK's credit record when repaying debt?","difficulty":"beginner","explanation":"Regular payments and early communication with lenders keep your credit record good."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Membayar minimum tepat waktu dan tidak mengabaikan kewajiban","options":["Membayar minimum tepat waktu dan tidak mengabaikan kewajiban","Meminjam dari banyak sumber","Membayar hanya utang terbesar","Menutup semua rekening bank"],"question":"Apa yang melindungi rekam kredit SLIK saat membayar utang?","difficulty":"beginner","explanation":"Keteraturan pembayaran dan komunikasi dini dengan pemberi pinjaman menjaga rekam kredit tetap baik."}$json$::jsonb where id = '30bd9a1e-f6da-4aa8-8a5a-e97e264c3585';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Using a credit card for emergencies is always bad.","difficulty":"beginner","explanation":"A credit card can be a useful emergency solution if you have plans to pay in full soon after."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Menggunakan kartu kredit untuk keadaan darurat selalu buruk.","difficulty":"beginner","explanation":"Kartu kredit bisa menjadi solusi darurat yang berguna jika kamu punya rencana untuk membayar penuh segera setelahnya."}$json$::jsonb where id = '310cb115-8c41-45cb-8bfa-ae6c6554e5b7';

